const i={ui:{fig:"Fig. 1",title:"Cosmetic bag · anatomy",svgLabel:"An isometric drawing of the lined zipper cosmetic bag with round corners and how it is sewn, step by step.",prev:"Previous step",dot:(e,t)=>e?`Step ${e}: ${t}`:t,start:"Steps →",next:"Next →",overview:"Overview",stepOf:(e,t)=>`Step ${e} of ${t}`,machine:e=>`Machine: ${e.toLowerCase()}`,inThisStep:"In this step",takeApart:"Take it apart",putTogether:"Put it together",replay:"↻ Replay",parts:"Parts",allSteps:"Step-by-step instructions",endView:"END VIEW",cutTitle:"Cosmetic bag · cutting sizes",cutAlt:"Cutting diagram for a lined zipper cosmetic bag: outer and lining 23 × 31 cm each, thin fusible interfacing 21 × 29 cm, four pink pieces 18 × 10 cm, a 16 × 16 cm square of interfacing for the round corners and a 20 cm zipper.",cutCaption:"The pieces to cut, with their sizes — the same as in step 1."},stitches:{straight:"Straight stitch"},labels:{cm23:"23 cm",cm31:"31 cm",cm29:"29 cm",cm21:"21 cm",cm18:"18 cm",cm10:"10 cm",cm16:"16 cm",cm20:"20 cm",cm1:"1 cm",cm35:"3.5 cm",cm25:"2.5 cm",outerCotton:"outer · cotton",liningCotton:"lining · same size",ifaceThin:"thin interfacing",pink4:"4 × pink",ifaceCorners:"for the corners",zipper:"zipper",radius8:"radius 8 cm",paperTemplate:"paper template",cutInHalf:"cut in half",twoHalves:"two half-circles",ironOn:"iron on",rightSides:"right sides together",alongEdge:"sew on its edge",makeTwo:"make two",trimNotch:"trim, notch the curve",turnOut:"turn right side out",wrongSideUp:"outer, wrong side up",edges1:"1 cm from the edges",middleBottom:"the middle = the bottom",rightSideUp:"right side up",onBottomLine:"on the bottom line",stitchRound:"stitch all round",straight05:"straight side: 0.5 cm",outerUp:"outer, right side up",zipperDown:"zipper face down",liningDown:"lining face down",seam05:"0.5 cm seam",liningAway:"open the lining out",foldBoth:"fold both in half",otherSide:"the other side",openZipper:"open the zipper",opening6:"6 cm opening",outerHalf:"outer",liningHalf:"lining",insideOut:"still inside out",cornersSewn:"corners sewn",cutCorners:"cut the corners",pinchSew:"pinch, sew across",seamOnFold:"side seam on the fold",allFour:"all four corners",turnThrough:"turn through the opening",byHand:"close it by hand",pushLining:"push the lining in",closeZip:"close the zipper"},steps:[{title:"The finished bag",text:"A lined zipper bag for make-up, pencils and creams: printed cotton with thin interfacing, a pink round corner at each end of the bottom. Tap the bag to take it apart."},{title:"Cut the pieces",text:"Outer and lining: 23 × 31 cm (9 × 12¼ in) each. Thin fusible interfacing: 21 × 29 cm (8¼ × 11⅜ in) and a 16 × 16 cm (6¼ in) square. Four pink pieces, 18 × 10 cm (7⅛ × 3⅞ in). A 20 cm (7⅞ in) zipper.",details:["From printed cotton cut the outer, 23 × 31 cm (9 × 12¼ in). Cut the lining the same size, 23 × 31 cm.","From thin fusible interfacing cut a 21 × 29 cm (8¼ × 11⅜ in) piece for the outer and a 16 × 16 cm (6¼ × 6¼ in) square for the round corners.","From pink cotton cut four pieces, 18 × 10 cm (7⅛ × 3⅞ in) — two for each corner.","You also need a 20 cm (7⅞ in) zipper.","Every seam allowance in this bag is 0.5 cm (³⁄₁₆ in)."]},{title:"Make the corner template",text:"Draw a circle of radius 8 cm (3⅛ in) on paper and cut it out. Trace it on the 16 × 16 cm (6¼ in) square of interfacing, cut the circle out and cut it in half.",details:["Make a paper template: a circle with a radius of 8 cm (3⅛ in).","Trace the circle on the 16 × 16 cm (6¼ in) square of interfacing and cut it out.","Cut the circle in half: two half-circles, one for each round corner."]},{title:"Sew the half-moons",text:"Iron a half-circle onto the wrong side of a pink piece, in the middle, its straight side 1 cm (⅜ in) from the long edge. Lay a second pink piece under it, right sides together, and sew along the curved edge of the interfacing.",details:["Lay a half-circle of interfacing, glue side down, on the wrong side of a pink piece: in the middle, its straight side 1 cm (⅜ in) from one long edge. Iron it on.","Put it on a second pink piece, right sides together.","Sew along the curve, right on the edge of the interfacing.","Make the second one the same way."]},{title:"Trim and turn",text:"Trim the fabric round the curve, notch the seam allowance and turn each half-moon right side out. Press.",details:["Cut away the extra fabric round the curve, leaving a narrow seam allowance.","Notch the allowance along the curve so it lies flat.","Turn both half-moons right side out through the straight side and press them. The straight side stays open."]},{title:"Fuse the interfacing",text:"Iron the 21 × 29 cm (8¼ × 11⅜ in) interfacing onto the wrong side of the outer, 1 cm (⅜ in) from every edge. Fold the outer in half and notch the middle: that is the bottom.",details:["Lay the outer wrong side up.","Place the interfacing on it, glue side down, 1 cm (⅜ in) in from every edge, and iron it on. The lining gets no interfacing.","Fold the outer in half across its length and snip a small notch at both ends of the fold. The fold is the bottom of the bag — there is no seam there."]},{title:"Sew on the half-moons",text:"On the right side of the outer, put a half-moon on each side edge, its middle on the bottom line, its straight edge level with the side. Stitch it all round.",details:["Turn the outer right side up.","Put a half-moon on each side edge: its straight raw edge level with the side edge of the outer, its middle on the notches — the bottom line.","Stitch each one all round: along the curve right on the edge, along the straight side 0.5 cm (³⁄₁₆ in) from the edge. The straight side will go into the side seam."]},{title:"Zipper: the first side",text:"Outer right side up, the zipper face down along one short side, in the middle, then the lining face down on top. Sew 0.5 cm (³⁄₁₆ in) from the edge.",details:["Lay the outer right side up.","Put the zipper face down along one 23 cm (9 in) side, in the middle: its ends stop short of the side edges, so they stay out of the side seams.","Lay the lining on top, face down, its edge level with the outer.","Sew through all the layers, 0.5 cm (³⁄₁₆ in) from the edge. No topstitching along the zipper."]},{title:"Zipper: the second side",text:"Open the lining out from the zipper. Fold the outer in half and the lining in half, so their other short sides meet the other side of the zipper, and sew it the same way.",details:["Open the lining out, away from the zipper.","Fold the outer in half on the bottom line, right sides together, and the lining in half the same way.","Their other short sides now meet the other side of the zipper: outer, zipper face down, lining — as before.","Sew 0.5 cm (³⁄₁₆ in) from the edge. The outer and the lining are now one loop."]},{title:"Sew the side seams",text:"Open the zipper. Lay the bag flat, outer on outer and lining on lining, right sides together, and sew both sides — leaving a 6 cm (2⅜ in) opening in the middle of one side of the lining.",details:["Open the zipper first: the bag will be turned out through it.","Lay it flat, the outer right sides together on one side of the zipper, the lining on the other.","Sew both side seams, 0.5 cm (³⁄₁₆ in) from the edge, through the half-moons too.","In one side of the lining leave 6 cm (2⅜ in) open, in the middle of the seam."]},{title:"Box the corners",text:"From each bottom corner — two on the outer, two on the lining — cut a 3.5 × 2.5 cm (1⅜ × 1 in) piece: 3.5 cm along the bottom, 2.5 cm along the side seam. Pinch each corner and sew straight across.",details:["Mark a 3.5 × 2.5 cm (1⅜ × 1 in) rectangle in each of the four bottom corners: 3.5 cm along the bottom, 2.5 cm along the side seam.","Cut them out.","Open each corner and flatten it so that the side seam lies on the bottom fold and the cut edges form one straight line.","Sew straight across, 0.5 cm (³⁄₁₆ in) from the edge. Do all four corners."]},{title:"Give it shape",text:"Open the bag out: with the corners sewn, the outer and the lining have each become a shape with a flat bottom. It is still inside out, the two joined by the open zipper.",details:["Spread out the outer and the lining: the bottom and the corners stand up, and you have two shapes.","The seams are on the outside and the open zipper sits between the two: the bag is still inside out."]},{title:"Turn it out",text:"Turn the bag right side out through the opening in the lining and the open zipper. Close the opening by hand, push the lining in and close the zipper.",details:["Pull the outer out through the opening in the lining and the open zipper.","Tuck in the raw edges of the opening and sew it closed by hand.","Push the lining into the bag, right into the corners, and close the zipper. The half-moons have turned into round pink corners."]}],legend:[{title:"Outer",text:"printed cotton · 23 × 31 cm (9 × 12¼ in), folded in half: the fold is the bottom"},{title:"Interfacing",text:"thin, fusible · 21 × 29 cm (8¼ × 11⅜ in), on the outer, 1 cm (⅜ in) from the edges"},{title:"Round corners ×2",text:"four pink pieces 18 × 10 cm (7⅛ × 3⅞ in) · half-circles of interfacing, radius 8 cm (3⅛ in), cut from a 16 × 16 cm (6¼ in) square"},{title:"Zipper",text:"20 cm (7⅞ in) · in the middle of the short sides, no topstitching"},{title:"Lining",text:"cotton · 23 × 31 cm (9 × 12¼ in), without interfacing"},{title:"Seams",text:"all 0.5 cm (³⁄₁₆ in) · a 6 cm (2⅜ in) opening in the lining, closed by hand · corners: 3.5 × 2.5 cm (1⅜ × 1 in) cut out"}]};export{i as default};
